class _Spy(list):
    seen = set()
    def __getitem__(self, i):
        _Spy.seen.add(i % len(self))
        return list.__getitem__(self, i)
    def __iter__(self):
        for i in range(len(self)):
            yield self[i]
s = _Spy([5, -1, 9, 9, 9, 9])
assert first_negative(s) == 1
assert max(_Spy.seen) <= 1, f'it looked at position {max(_Spy.seen)}, past the first negative at 1; stop once you find it'

